# Cross-Database Schema Mapper - runnable demo (JAH-ATK183S-000001)
import difflib
RANK = 1
SIG = True
SCHEMA_A, SCHEMA_B = [[('cust_name', 'text'), ('cust_id', 'int'), ('joined', 'date')], [('customerName', 'text'), ('customer_id', 'int'), ('signup_date', 'date'), ('notes', 'text')]]  # lists of (name, type)
def name_sim(a, b):
    return difflib.SequenceMatcher(None, a.lower(), b.lower()).ratio()
mappings, used = [], set()
for name_a, type_a in SCHEMA_A:
    best, bs = None, 0.0
    for name_b, type_b in SCHEMA_B:
        if name_b in used: continue
        s = 0.7*name_sim(name_a, name_b) + 0.3*(1.0 if type_a == type_b else 0.0)
        if s > bs: best, bs = (name_b, type_b, s), s
    if best and bs >= 0.45:
        mappings.append((name_a, best[0], round(bs, 2))); used.add(best[0])
    else:
        mappings.append((name_a, None, 0.0))
for a, b, s in mappings:
    print("%-14s -> %-14s (%.2f)" % (a, b or "UNMAPPED", s))
if RANK >= 3:
    mapped = sum(1 for _, b, _ in mappings if b)
    print("coverage: %d/%d fields mapped" % (mapped, len(mappings)))
if SIG:
    print("Signature lineage stamp: JAH-SIG-SCH-" + "JAH-ATK183S-000001")
print("record:", "JAH-ATK183S-000001", "OK")

